index 0000000..bea92f1
--- /dev/null
+++ b/scripts/check-genai-migration.mjs
@@ -0,0 +1,13 @@
+import fs from "node:fs"
+const bad = []
+const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"))
+if (pkg.dependencies["@google/generative-ai"]) bad.push("old package still in package.json")
+if (!pkg.dependencies["@google/genai"]) bad.push("@google/genai missing")
+for (const f of ["app/api/ai/chat/route.ts", "lib/ai-advanced-utils.ts", "lib/ai-client.ts", "lib/ai-utils.ts"]) {
+  const src = fs.readFileSync(f, "utf8").split("\n").filter((l) => !l.trim().startsWith("//")).join("\n")
+  if (/generative-ai|getGenerativeModel|\.response\b|\.text\(\)/.test(src)) bad.push(f + ": legacy API")
+  if (!/ai\.models\.generateContent/.test(src)) bad.push(f + ": no ai.models.generateContent")
+  if (/gemini-2\.0-flash/.test(src)) bad.push(f + ": retired model")
+}
+if (bad.length) { console.error(bad.join("\n")); process.exit(1) }
+console.log("ok")
